INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p238084-engl002', 'stk-user3659', 'ENGL 002', 'info', '{"desc": "لالالالا عزيزي اقصد engl002 انا ضمن الطلاب الذين اخذوا الكورس الجديد ولسوء الحظ وضعوا معنا طلاب بورموشن من دفعت 2007 في الميد ترم صارالافرج 79.3 بسبب فصل البورموشن (وكان الافرج بالنسبه لهم 86)\nفماااااااااااااااااااااااااذ تتوقع يكون افرج النجاح علماً بان الاختبار النهائي صعب صعب لكن سهل عندهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/60980/4", "user": "user3659", "ts": 1200957804000, "tid": 60980, "pn": 4}}', 1200957804000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p271010-engl002', 'stk-s2007xxxx', 'ENGL 002', 'info', '{"desc": "طيب وش فيك ياخوي معصب\n\nصحيح اوريا احممممم\n\nقصدي بالنسبة لREADING ذاكر BOOK 4 الى TEXT 28 راح تجي 3 تكست واحد من الكتاب واثنين من برا\n\nبالنسبة لLISTENING راح يكون اكيد من برا المنهج تستمع للكونفرسايشن وتاخذ نووت تالي تجاوب\n\nوبالنسبة لWRITING راح يكون سؤالين\n\nالاول COMPARE & CONSTRACT\n\nالثاني WRITE 3 PARAGRAPHS TO DESCRIBE SOME THING", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/63477/2", "user": "s2007xxxx", "ts": 1212414949000, "tid": 63477, "pn": 2}}', 1212414949000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p659899-engl002', 'stk-user5900', 'ENGL 002', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nأسعد الله أيامكم باليُمن والبركات 👍\n\nحبيت أفتح نافذة يا شباب لتجميع أكبر قدر من المعلومات عن اختبار الرايتنق اللي راح يكون\nيوم الاثنين 26 / 7 / 2010 😏\n\nفنبغى نعرف المواضيع من مدرسينكم لأن بعض المدرسين ( عنده سطوه ) على الادارة ويقدر يجيب\nمعلومات عن الاختبار و المواضيع خصوصاً للـopinion essay 😆\n\nهذا ما احببت الاشارة اليه وشكراً … 🤓", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/92176/1", "user": "user5900", "ts": 1279391539000, "tid": 92176, "pn": 1}}', 1279391539000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p857523-engl002', 'stk-user7305', 'ENGL 002', 'info', '{"desc": "3- vincent mccarthy\n\nأنا أخذت معه انقلش 002 هالترم\nمدرس الحقيقة أكذوب لو أقول أنه بطل !\nلكن حظك حلو أنك نزلت عنده … لأنه حررررريص على طلابه\nو يموووت عشان يساعدهم ياخذون قريد بالتوفل\nمشكلته انه روتيني … و اذا انت اخلاق و تشارك معه ابشر بالدرجات و الايفورت\nلا تحاول تستخف دمك او تسوي ظريف … هو لا يبتسم و لا شيء\nما رح يضحك الا باخر الاسابيع … جدي لأبعد درجه و يبي طلابه جديين\nما فيه هومووركات الا ما ندر !\n\nيحب الكتاب الازرق تبع القرامر و دايم يستخدمه …\n\n/\n\nاعطاني درجات بالهبل و اخذت A و انا ما افتح الانقلش الترم الماضي\nبس لاني فهمت عليه من بدري و صرت جدي مرره و اشارك و لا اسولف و لا استهبل ابد ابد\n\n/\n\nموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/108717/7", "user": "user7305", "ts": 1308739429000, "tid": 108717, "pn": 7}}', 1308739429000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p833456-engl002', 'stk-user6913', 'ENGL 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nانا كنت الترم الماضي بـ002 انقلش\n\nبالنسبة للتكنولوجي … يعتبر من سهل الى متوسط بالنسبة لي وانا كان مستواي عادي\n\nنصيحة فيها اقرا الكلمات اللي باخر الكتاب وترجمها … وانشالله تاخذ درجة بالعلالي\n… اذا انت دايم منتبه بالكويزات وكذا تعتبر بالسليم …\nواللسننق ركز ودرجتك تكون عالية فيه\n\nفيه الموقع حقهم الاكسفورد تلقاه بالغلاف الخلفي بالكتاب ادخله وفيه اختبارات مشابهه للاختبار وكذا انا فادتني كثييير\n\nكل كلامي عن التكنولوجي … لان كان الهدواي ظالمينا فيه … من غير الكتابة\n\nانت ذاكر زين وتوكل على الله وماعليك … تحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-technology-headway/106398/3", "user": "user6913", "ts": 1302987120000, "tid": 106398, "pn": 3}}', 1302987120000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p833754-engl002', 'stk-user7729', 'ENGL 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nانا كنت الترم الماضي بـ002 انقلش\n\nبالنسبة للتكنولوجي … يعتبر من سهل الى متوسط بالنسبة لي وانا كان مستواي عادي\n\nنصيحة فيها اقرا الكلمات اللي باخر الكتاب وترجمها … وانشالله تاخذ درجة بالعلالي\n… اذا انت دايم منتبه بالكويزات وكذا تعتبر بالسليم …\nواللسننق ركز ودرجتك تكون عالية فيه\n\nفيه الموقع حقهم الاكسفورد تلقاه بالغلاف الخلفي بالكتاب ادخله وفيه اختبارات مشابهه للاختبار وكذا انا فادتني كثييير\n\nكل كلامي عن التكنولوجي … لان كان الهدواي ظالمينا فيه … من غير الكتابة\n\nانت ذاكر زين وتوكل على الله وماعليك … تحياتي\n\nيعطيك العافية اخوي طربق طربق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-technology-headway/106398/4", "user": "user7729", "ts": 1303066593000, "tid": 106398, "pn": 4}}', 1303066593000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p379935-engl002', 'stk-user4329', 'ENGL 002', 'info', '{"desc": "S\\!SsOkOلو انـــك عندي حبيت راســـك على ذي المعلومااااات المهمــــــــــــــه جدا جدا جدا\n\nوالله انك ما قصررررت , الله يجزاك الف خير ويبيض وجهــك\n\nومن ناحيــة ان 3 ايام ولا احد رد ( فحن نحسن الظن بالشباب يمكن مشغولين يمكن ما احد قرأ الموضوع )\nلكـــن نتمنى منهم اذا قروا الموضوع ,\n\n1- يقولون لنا كيف اسألة اللليسننق , وكيف نقدر نذاكره من اللحين\n\n2- كيف اسألة الريدنق , وكيف نقدر نذاكره\n\n3- ^ ^^ الليسننق , وكيف نقدر نذاكره\n\n4- ^^ ^^ السبيكنق , ^^ ^ ^^\n\nنبيهاااا بالتفصيل الممـــــــــــــــــــــل\n\nلأني متأكد 90% ان أساله الميد تيرم هذا راح تكون شبيهــــة تماما للاختبار اللي راح , لأنه اللي يحطون الأسالة غير متشددين وكلكـم عارفين باللي صار في الفاينل من تطابق في الأسألة < وهذا يأكد كلامي\n\nفيا شباااااب ننتظــر اجوبتكم بفارغ الصبر الله يزووووجكم ساعدونا …!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english002/71396/20", "user": "user4329", "ts": 1236877596000, "tid": 71396, "pn": 20}}', 1236877596000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p379904-engl002', 'stk-s_ssoko', 'ENGL 002', 'info', '{"desc": "خخخخخخخخخخخ من 3 أيام ما رد عليكم ولا واحد 😆\n\nطيب يا شباب ، أول شي الله يوفقكم بالـ 002\n\nالمنهج مب صعب وحتى لو لقيت كلمات صعبة كثير وجديدة عليك بالكتاب لا تهتم لها كثير لأن الاختبار أسهل بكثير من مستوى الكتاب\n\nأسئلة الميد تيرم في الرايتينغ كانت عبارة عن رسالة شكوى 120 كلمة وتكتب عن شيء حصل لك في الماضي 180 كلمة << غالبًا تكتب عن رحلة قمت بها\n\nالليسيننغ كالعادة شريط تسمعه من الكمبيوتر يعيده لك مرتين ، لكنه أسرع من الشريط اللي كنتم تسمعونه في الـ 001\n\nالريدينغ يعطيك 4 قطع مثلاً ويحط لك 15 معلومة وأنت تربط المعلومة بالقطعة ، وطبعًا لازم يجيب لك قطعة طويلة وعليها أسئلة\n\nالسبيكينغ في الميد تيرم يسألك المدرس سؤالين عن موضوع ، مثلاً ممكن يقلك لو كنت الملك ما القرار الذي ستتخذه ، ما الشيء الذي تملكه في دولتك ولا تملكه دول أخرى ، غالبًا تكون أسئلة يبيلها تفكير ، بعدها أنت وخويك تاخذون الورق وتصير عندك أنت معلومات وهو يبي يستفسر\n\nمثلاً أنت ورقتك مكتوب فيها معلومات عن مدينة معينة ، وخويك ورقته مكتوب فيها إنه مقيم جديد في المنطقة ويبي يستفسر عن بعض الأماكن\n\nيصير خويك يسألك وأنت تجاوب عليه على حسب المعلومات اللي عندك وتتبادلون بعضها\n\nآخر شي في السبيكينغ تستلم أنت وخويك صورتين وتتحدثون عنهم ، أنا جتني صورة زروق وقارب صغير قعدنا أنا وخويي نتكلم عنها وقلنا رأينا فيها وكذا\n\nالشغلة سهلة بس يبيلها تركيز\n\nفيه نقطة لازم أنبهكم لها ، فيه مدرس في السبيكينغ ما اختبر الطلاب الاختبار حق الصورتين ومافيه أحد من الطلاب اللي كانوا عنده جابوا فوق الـ 80 ، لو جاكم هالمدرس لا سمح الله حاولوا تلقطون اسمه وانسبوا لكيفن مور\n\nفالكم النجاح إن شاء الله 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english002/71396/19", "user": "S_SsOkO", "ts": 1236872876000, "tid": 71396, "pn": 19}}', 1236872876000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1040166-engl002', 'stk-alopeed', 'ENGL 002', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nكلنا يعرف إن الاختبار يوم الثلاثاء وأنا وضعت هذا الموضوع بدري عشان الكل يستفيد بإذن الله\nالخلاصة : انه اذا احد يعرف عن هذا الاختبار شي من ناحية توزيع الدرجات , المدة , كم ريدنق , كم اللسن , وغيرها من الآسئلة .\n\nالشئ الثاني : Reading هل له مذاكرة يعني من فين يجيبونها وهل اذا قريت التكنولوجي راح يفيدني .\n\nالشئ الثالث : هل في اسئلة مراجعة , إختبارات قديمة , اللي عنده لايبخل علينا وله الدعاء .\n\nهذا كل شئ والسلام عليكم\n\nتمنياتي بالتوفيق\n\n🌹 🌹 🌹 🌹 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002/125852/1", "user": "alopeed", "ts": 1337489798000, "tid": 125852, "pn": 1}}', 1337489798000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1040173-engl002', 'stk-besooo', 'ENGL 002', 'info', '{"desc": "ذا الانوانسمنت حق scott مسؤؤل البلاك بورد\n\n\"This exam tests the materials covered in Technology 2 (except Unit 14) and Focus on Reading 4. The structure looks like this:\n\nListening: 30 items based on 5 audio recordings featuring our own PYP voice talent. The topics are closely related to the Tech 2 themes. (25%)\nUse of English: 50 items on grammar and vocabulary from Tech 2 and 10 items on vocabulary from Focus on Reading 4. (50%)\nReading: 30 items about 3 texts of 250-350 words on topics closely related to the Tech 2 themes. (25%)\nEach item is equally weighted. The total test time is 1 hour and 50 minutes (110 minutes).\n\nPlease feel free to share this information with your students.\n\nScott Surran\n002 coordinator\"\n\nبالتوفيق ان ش الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002/125852/2", "user": "besooo", "ts": 1337491207000, "tid": 125852, "pn": 2}}', 1337491207000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p363498-engl002', 'stk-user4212', 'ENGL 002', 'info', '{"desc": "الدرجة الاخيرة مالها دخل بالاختبار الاول …\nماخوذة من الاختبار اللي سبق الفاينل\n\nاما العلامة اللي حاطينها بموقع السنة التحضيرية فـ لها طريقة خاصة بالحساب\nاللي يجيب فوق الـ 65 يعطونه الـ 100 كاملة << 10%\nواللي يجيب 60 مثلا يعطونه 95 …\nواللي 55 يعطونه 90 … الخ\n\nاما الدرجة الفعلية كم جبت بالامتحان ننتظرها على موقع الاي بي تي،، مع اني احس انهم ما بينزلونها ابد 🤓", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ept-eng-002/70207/32", "user": "user4212", "ts": 1234086661000, "tid": 70207, "pn": 32}}', 1234086661000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p994540-engl002', 'stk-user6801', 'ENGL 002', 'info', '{"desc": "اخي الغالي\n\nانت صدقني مستواك جيد في الانقليزي بما أنك عديت 001\n\nكل انك تتعلم كيف مهارة الكتابة\n\nلا أعلم ما هي مواضيعكم في هذا الفصل\nلكن لنقل رسالة شكوى Complain\n\nاعرف كيف ترتب الكتابة\n\nفي البداية تكتب الافتتاحية أو المقدمه ( خلاص هاذي قبل الاختبار تكون حافظ افتتاحية أو مقدمه تكون شاملة لأي نص يطلبة منك المدرس ) ممكن تقول كيف أحصل عليها قبل الاختبار حاول تأخذ من أحد الطلاب الدوافير أو من نص الكتاب وتزيد عليها كلمتين وتروح تسأل المدرس عنها كيف\n\nفي البدي : تحاول تعرف الكلمات الي تربط الجمل مثل NEXT,IN addition, Furthermore\nوتلعب لعبتك\n\nالخاتمه بتكون واحده في كل مقالات الشكوى يعنيك عليك تحفظها قبل الاختبار\n\nوكذلك فيه طريقة أنك تروح للمدرس بأستمرار في الاوفس أور وكل تكتب له أي تعبير جمله ومالك الا تطور عمرك\n\nاما المدرس الخصوصي اش بيفيدك فيه اذا كان انت ما اجتهدت\n\nحاول تحفظ كلمات قدر ما تستطيع\n\nوحتى اكون معك صريح كان الانحليزي عندي ميح لكن الحمدلله اجتزت الاوريا بهذه الطريقه والتي هي اني ادخل اختبار الرايتنق وانا حافظ لي ما يقارب من خمسين بالمئة من الاختبار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english002/121853/2", "user": "user6801", "ts": 1330292213000, "tid": 121853, "pn": 2}}', 1330292213000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p781803-engl002', 'stk-woood', 'ENGL 002', 'info', '{"desc": "آهــلا فيك اخوي في kfupm\nبالنسبة للانجلش 002 ما في خمس ساعات\nوبالنسبة للماث ما عليك سهل ولا صعب ذاكر اول باول وفالك +A\nاما بالنسبة لباقي المواد والله ما آدري\nتاخذهم كلهم في السمستر الثاني\nاو تاخذ منهم في الصيف\nوهذي معــلومات عن انجلش 002\nhttp://www.kfupm.edu.sa/PYP/002assessment.html\nوآقـــولك …\nفـــالك التوفيق\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/102040/2", "user": "WoOoD", "ts": 1296903699000, "tid": 102040, "pn": 2}}', 1296903699000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1113866-engl002', 'stk-salman-10', 'ENGL 002', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nحبيت استفسر من الطلاب اللي درسوا انجليزي 02 كيف كان معاهم الكورس وكيف كان اللفل صعب ولا سهل وكيف طريقة المذاكرة في الكويزات\n\nوكيف كانوا المدرسين\n\nلاني انا ولله الحمد عديت 01 وحبيت استفسر عن اللفل الجديد اللي راح ادرسه\n\nفياليت تفيدوني واكون شاكر لكم ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english02/134311/1", "user": "Salman-10", "ts": 1352321244000, "tid": 134311, "pn": 1}}', 1352321244000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1116034-engl002', 'stk-heshy', 'ENGL 002', 'info', '{"desc": "انا حاليا عدت الكورس بسبب خسيس\nلان الافرج حق سكشنا كان فرق السما عن الارض\nبين اللي بعدنا\nنقصوا من كل طالب حول 15 درجة\nلكن نقول الحمد لله\n\nالتركيز في هذا الكورس بكون على الرايتينق والليسنينق\nالقرامر اللي تاخذوه لازم تطبقه في الرايتنق\nواي سؤال انا حاظر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english02/134311/2", "user": "HESHY", "ts": 1352702745000, "tid": 134311, "pn": 2}}', 1352702745000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p152857-engl002', 'stk-red-devil', 'ENGL 002', 'info', '{"desc": "شكرا على المعلومات…\n\nطيب بالنسبة للـEnglish 002\nدرسني شخصين:\nالأول:- (Solar Snyman) جنوب أفريقي…\nمدرس شرحه يعني مو مررررررررررررة بس أنواع الفلة…\nيعني اللي يبي الفلة وشوية معلومات فهذا المدرس المطلوب…\nالثاني:- (John Ablorh) وهذا بريطاني…\nمدرس ممتاز جدا من ناحية الشرح…\nوصراحة الكتابة حقتي تحسنت معاه…\nلكن مدرس مررررررررررررررررررررة قروشة…\nيعني لو تأخرت لا تدق الباب والا بتآخذلك ذيك التشميقه…\n\nبالنسبة للمهارات الجامعية:\nدرسني الدكتور سالم الديني…\nوالله انسان فاضل وله كل المعزة والمحبة والتقدير…\nصراحة مدرس من أبدع ما يكون…\nواللي جاته المهارات معاه…\nفيا هنياله…\n\nوأما الـMath:\nفدرسني واحد اسمه (Brym Demayr)\nأو “دمار كما يسميه البعض”\nلووووووووووووووووول\nالمهم شرحه تمام وكل شي فيه عجبني…\nيعني مدرس مزبوط بس مو بالشكل الكامل…\nالمهم انو تمام…\n\nوأما الفيزياء والـPE فما أبغى أتكلم عنها لانو لو بدأت ما راح أوقف حش…\nخخخخخخخخااااااااااااااااااااااااي\nما ناسبوني المدرسين…\nلكن ما أبي أذكر الاسماء…\n\nوهذا كلش…\n\nتحياتو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/54933/28", "user": "red-devil", "ts": 1171733487000, "tid": 54933, "pn": 28}}', 1171733487000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p548180-engl002', 'stk-user6690', 'ENGL 002', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nاخواني الاعزاء\n\nكما هو معلوم ان انقلش 002 مليء بالكلمات الجديده فحبيت اساعدكم\n\nعندي ملف ورد فيه تقريبا اكثر الكلمات الجديده اللي بكتاب الانقلش\n\nومترجمة بالعربي ونصيحة مني مدام انتو في بداية السمستر حاولوا تحفظوها\n\nلانها بتنفعكم بالريدنق والرايتنغ والسبيكنغ وكمان الليسننغ\n\nعلما بانها كلمات الكتابين اللي بتاخذوهم في 002 يعني الميدتيرم والفاينل\n\nوشكرا لكم\n\nهذا رابط التحميل\n\nhttp://file8.9q9q.net/Download/94987772/abandon.rar.html", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/84205/1", "user": "user6690", "ts": 1266784553000, "tid": 84205, "pn": 1}}', 1266784553000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1246782-engl002', 'stk-sultan2s2', 'ENGL 002', 'info', '{"desc": "شوف توكل على الله ولا تيأس\nترى الكوزات ليست سر النجاح تقدر تبدع في الفاينل وتعدي زي السلام عليكم\n\nبس ذاكر مو تسحب على الهرجه و على بالك بيدفونك مستحيل تراك بالبترول\nالمهم يا أخويي بدال وصلت لأخر المشوار* اللي هوا الفاينل* معد يفيدك تروح تحفظ الليسنينق\n*كل اللي عليك الأن تدرب على الريدنق من كتب ثانيه قصص على سبيل المثال والقرمر حاول تلحق نفسك فييه والفوكاب هذا اللي تقدر تسويه وبس وأنشاء الله فالك النجاح *", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng-02/147118/2", "user": "sultan2s2", "ts": 1374144656000, "tid": 147118, "pn": 2}}', 1374144656000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1173983-engl002', 'stk-user9213', 'ENGL 002', 'info', '{"desc": "عموما القرامر هو من اليونتس المحددة بالسكاجول اللي اعطونا اياه هذا اولا ثانيا الكتاب الازرق حق اللسننق والسبيكينق والثاني حق الرايتنق والريدينق هذي مع المدرس تفهمها وتناقشها وتحفظ الفوكاب اللي باخر كتاب الريدينق والرايتنق وهذي الطريقة اللي اتبعها الان وتمنياتي بالتوفيق لكم ولنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-02/139392/11", "user": "user9213", "ts": 1359631445000, "tid": 139392, "pn": 11}}', 1359631445000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p652399-engl002', 'stk-3boody830', 'ENGL 002', 'info', '{"desc": "شوف حبيبي انا كنت جايب بالمدتيرم 65 وبالنهايه عديت الكورس ب c+ الحمد لله …\n\nالطريقه اني بعد ما شفت درجه المدتيرم انصدمت وقل لازم اعدي باي طريقه ف حطيت لي خطه اني احفظ كل الفوكاب اللي بالكتاب قبل الفاينل وتقريبا خلصت أغلب الفوكاب خصوصا الاكادمك وورد .\nوجبت بالريدنق حق الفاينل فل مارك الا شوي مع اني كنت بالمد تيرم 46 !!\n\nفأشوف من وجهت نظري ان الفوكاب اهم شي …\nوبالتوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/91590/3", "user": "3boody830", "ts": 1278366887000, "tid": 91590, "pn": 3}}', 1278366887000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p837338-engl002', 'stk-a_o_s_ll', 'ENGL 002', 'info', '{"desc": "بكل امانه كان الاختبار تافه وبسيط بالنسبه لي\nولـ الله الحمد\nوانا استغربت صراحه 😲\nكنت متوقع اصعب بكثيييير\nوحتى السامبلس اللي حطوها بالموقع كانت اصعب من الاختبار نفسه\n\nواللهم لك الحمد وان شاء الله الرايتنق والريدنق يكونون مثل المستوى\nيا رب 😭\n\nوالله يوفقكم يا شباب وفالكم الدرجات الحلوه اللي تبيض الوجه ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002-tech-1-mid-term/106806/2", "user": "A_O_S_ll", "ts": 1303829930000, "tid": 106806, "pn": 2}}', 1303829930000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p435152-engl002', 'stk-dark-future', 'ENGL 002', 'info', '{"desc": "السلام عليكم يا إخوان\n\nمثل ما صار الفاينل الماضي في ترم 82 نزل صفحات تبين المطلوب من الكتاب للفاينل أو الميد تيرم\n\nالحين عندنا الميد تيرم قريب جدا\n\nفلذلك اللي عنده الورقة ينزلها سواء حقت الترم الماضي أو الحين لإن الاختبارين ما راح تفرق هيا هيا\n\nرجاء يا اخوان اللي عنده يستعجل فيها\n\nموفقين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng002/75831/1", "user": "DaRk-FuTuRe", "ts": 1248353735000, "tid": 75831, "pn": 1}}', 1248353735000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p862093-engl002', 'stk-mohannad_sa', 'ENGL 002', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nمثل ما هو واضح في الموضوع , أنا طالب English 002 ومستواي في الـ Listening و الـ Reading توب , أما في الـ Writing و الـ Speaking وضعي جيد بس مو مره , لكن ما عذبني إلا الـ Grammar الله يعيني عليه … 😐\n\nالزبدة اللي عنده موقع ممتاز للقرامر لا يبخل علي , وأهم شيء يكون الموقع متكامل , يعني كل القرامر للغة الإنجليزية موجودة فيه … 🤪\n\nالله يجزاه ألف خير اللي يقدر يفيدني وفاله الـ First honor … 🌹\n\nهمسه : بغيت اكتب الموضوع في السنة التحضيرية لكن ما عندك أحد القسم نايم , وأشوف موضوعي بصراحة أكاديمي , فالرجاء من المشرف عدم نقل الموضوع وله جزيل الشكر … 🥊", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english/109276/1", "user": "Mohannad_sa", "ts": 1309576095000, "tid": 109276, "pn": 1}}', 1309576095000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1426114-engl002', 'stk-abdulazizm', 'ENGL 002', 'info', '{"desc": "engl 002 عليك بصفحات الجرامر اخر الكتاب … هي ماهي كثيره لكن لو فهمتها صح امورك طيبه واذا تبي تآكد فهمك روح جوجل واكتب ا جرامر تبي تطبق عليه وحل + احفظ الفوكاب المطلوب + الريدينق اقرا القطع المطلوبه وافهم كل كلمه فيها سواء الاحمر ولا غيره لانه احينا يسآلون في الريدينق عن معاني كلمات غير المطلوب + اللسينينق اسمع اللي في اخر الكتاب مره مرتين قبل الكويز وافهمه وامورك طيبه + الرايتينق اتوقع بدربكم المدرس عليها\n\nللمعلوميه ( 02 حاول تفهمه صح لانه تقريبا شامل في الاساسيات وجدا مفيد وفي 03 راح يفيدك ويسهل لك الكورس )\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/169684/5", "user": "abdulazizm", "ts": 1440749138000, "tid": 169684, "pn": 5}}', 1440749138000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p601545-engl002', 'stk-aliiii', 'ENGL 002', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n--------------\n\nملف الوورد يتكلم … وصل يوم الربوع في البورتال لمدرسين الانقلش\n\nMediafire او multiupload\n\nالرايتنق قطعتين بس … فلة صح …\n\nوحدة 300 كلمة والثانية 150 … ما أدري من وين بطلع 300 كلمة في قطعة وحدة\n\n------------------\nطبعا يا شباب باقي تقريبا على الدراسة شهر واحد بس\n\nوالدليل …\n\nhttp://img696.imageshack.us/img696/7374/48552262.jpg\n\nوطبعا أكثر من ثلث الدفعة على حفة النجاح >> و :raised_hand: 😁\n(طبعا فيه ناس في الانجلش وناس في الماث وناس في الاثنين … والله يعين الجميع)\n\nولكن … وحط تحتها خطين مو واحد …\n\nالحين باقي شهر على الانجلش (ممكن تصير معجزات في هذا الشهر… بس كله يعتمد عليك وعلى شغلك)\n\nفإذا ماتوفقت في الاختبار اللي راح … فالفرصة بالتأكيد مازالت مستمرة\nلأنه الميد تيرم ما عيه الا 26 % يعني لو مرة مرة بيكون فاتك 13 بالمئة\n\nhttp://img641.imageshack.us/img641/6245/80614114.jpg\n\n*وطبقا لهذه الصورة …\n*وكما هو معروف أن الجامعة ليست متساهلة معنا في هذا السمستر …\n*وأن ال25 درجة التي في يد المدرس بس كلام (هاذي لها قصة لحالها … بكتبها لكم تحت للي مايعرفها )\n*وبحسبة بسيطة …\nتحتاج 20 في الميد تيرم +30 في الفاينل+18 من المدرس + 2 في التوفل (والتوفل له قصة 😏) = 70 وهي درجة الباس (رغم انه البعض يقول 68 )\n\n-------------------------\n\nأدري كثرت حكي 😆\n\n------------------------\nمعلومات للي مايدري بها … لكي تكونوا على علم 🙂\n* تم ارسال ايميل لجميع مدرسين الانجلش … لا زم تعطوا على الأقل 5 إنذارات لأي خمسة طلاب بشأن الواجبات … حتى لو كانوا يحلوا الواجبات !\n\n* تم ارسال معلومات للمدرسين تفيد انه يستحيييييل أي طالب في أي كلاس ياخذ فوق 85 %تقريبا (مو متأكد من الرقم … ممكن أعلى بشوي أو أقل) من 25 درجة عشان الأفرج يكون نازل … وتساوي جميع طلاب الكلاسات … لأن كما هو معرف فإحنا الطلاب مقسمين في الكلاسات على قريداتنا …فهم يشيلوا درجات من المرتفعين عشان يرفعوا النازلين ويكون الكلاس متوازن\n(أي طالب ترصد له فوق %85 تقريبا ---- الكمبيوتر بينزلها اوتماتكلي )\n\n*التوفل … اللي يجيب أقل من 350 بياخذ 0 من ال 10 الدرجات 😡 :speech_balloon:\nوأي 15 درجة أعلى من 350 يجيبها الطالب تحسب له بدرجة واحدة فقط\nأنا إختبرت السمستر الأول جبت 400 إلا درجتين الله يعين …صعب والوقت مشكلة\n-----------------\nبالتوفيييق …\n\nوالماث يوم الخميس ذاكروا يوميا ولا تحرموا نفسكم من اللعب (شوي بس 😆) والله يساعدنا ويساعدكم\nالماث إختبار مصيري بالنسبة إلي دعواتكم لي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/welcome-to-hell-info-about-eng-002-final-exam-and-somethig-else/87741/1", "user": "aliiii", "ts": 1273254303000, "tid": 87741, "pn": 1}}', 1273254303000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1014761-engl002', 'stk-chelsea_21', 'ENGL 002', 'info', '{"desc": "اذا تبي درجات عالية بكويزات 002 انجلش ( من 27 الى 35)\n\nذاكر الفوكاب من الورد ليست اخر كل unit ماراح يجيبون غيرها\n\nوالقرامر آخر الصفحة + قراءة language spot…\n\nبخصوص اللستيننق هو عليهم … مايحتاج مذاكرة بس يبيلك تسمع وتلقط الأجابة وقت الكويز\nسهله جدًا\n\nبخصوص الريدينق لاتشيل همه كل يوم ذاكر درس من الدروس الاربعة الي بالوحدتين\nمع ترجمة الكلمات (الي انت ماتعرفها) لانه يجي هالسؤال … واسئل نفسك بعد ماتخلص كل براقراف\nwhat this paragraph mainly about? لانه راح يجي هالسؤال\n\n-\n\nبخصوص الرايتينغ … اذا حليت مع مدرسك بالكلاس راح تكون مذاكرة بنفس الوقت\nواذا مرة تبي تجيب درجة عالية ذاكرة على مدار الاسبوع كل يوم حل براغراف حتى لو كنت تعرف بس عشان تتعود", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/123488/3", "user": "Chelsea_21", "ts": 1332693291000, "tid": 123488, "pn": 3}}', 1332693291000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1014906-engl002', 'stk-hasan_ali', 'ENGL 002', 'info', '{"desc": "طريقة مذاكرتي كانت كالتالي\nالـquizzes هي أهم شي دايم أحاول أجيب درجة كاملة لكن للأسف مستواي بشكل عام ضعيف لأني دخلت 002 عن طريق الحظ في إختبار الـ TOEFL الكلمات المفتاحية أذاكرها عن طريق الـglossory حتى لو كنت عارفها 100% والقواعد أذاكرها من آخر الكتاب وأدخل الإنترنت بعض الأحيان للتمرينات والمعلومات الإضافية\nللأسف كنت ما أحل الـwebCT لكن نصيحيتي لك حلها أنا لو حليتها كان جبت A\nالإختبار النهائي ما ذاكرت لأني مذاكر من الـquizzes ولو ذاكرت كان جبت نفس الدرجة\nوكنت أتعلم الكلمات الأكثر تكراراً 3000 most frequent words عن طريق الـ Longman في كلمات باللون الأحمر هذي كانت تفيد لغتي بشكل عام وبالتالي تفيد في الـ writing\nفي الأخير درجتي النهائية هي B+ وأستاذنا كان زفت طول اليوم وهو يحكي سواليف ويتكلم في مواضيع خارج المنهج ولكنه ساعدني في درجاتي وخاصة درجات الكتابة يعطيني في التسعينات فأعطيته ممتاز في تقييم المدرسين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/123488/4", "user": "hasan_ali", "ts": 1332791002000, "tid": 123488, "pn": 4}}', 1332791002000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p629229-engl002', 'stk-mr-3b0d', 'ENGL 002', 'info', '{"desc": "تافه\n\nالليسيننغ:الاولى كندا:كانت تاااافهه\nالثانية عن المبالغ اللي ياخذونها الرياضيين كثيرة عليهم وزي كذا ومقابلين مع لاعب سابق ومعلق حاليا^^\nوكانت الاصعب نسبياً\n\nالثالثة:كانت ارقيومنت عن السباحة في المحيط او احواض السباحة وكان تافه ايضا\n\nلدرجة اني ما اعتقد عندي أكثر من 3 أخطاء في الليسننغ maximum\n\nالريدينغ سهل\n\nالقطعة الاولى تتكلم عن مبيعات jay’s للجينزات وكان قراف -تافه\n\nالثانية تتكلم عن حوادث بسبب السرعة وكانت اصعب السهل -مقال صحفي-\n\nالثالثة كانت مقارنه بين الارجنتين والبرازيل وكانت تافهه باستثناء سؤالين كانوا في مستوى متوسط\n\nعموما الاختبار يتطلب تركيز شوي في كل كلمة في السؤال علشان تفهمه والباقي سهلات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002-final/89809/15", "user": "mr-3b0d", "ts": 1276344063000, "tid": 89809, "pn": 15}}', 1276344063000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p89912-engl002', 'stk-masm007sa', 'ENGL 002', 'info', '{"desc": "أخي الكريم ، أولا السلام عليدم ورحمة الله وبركاته\n\nلكي تستطيع أن تقوم بإضافة ENGLISH 101 بحصل ذلك بأحد أمرين :\n\nأن تكون قد حصلت على درجة A أو أكثر في ENGLISH002 .\nأو\n\nأن تكون قد اجتزت اختبار الPROMOTION للـ EINGLISH002 .\nوعلى ذلك تستطيع الحصول على وقة من الـ UEP DIRECTOR وهو Mr .Gibson ومكتبه يقع في الطابق الثاني في مبنى السنة التحضيرية اللي ملاصق للكفيتيريا، ومن هناك تطلب منه approval وهي ورقة يعطيك اياها ثم تتوجه بعدها لمبنى 11 في الأيام ا لمحددة على الرابط التالي:\n\nhttp://regweb.kfupm.edu.sa/052/event052.htm\n\nلأوفر عليك تعب البحث اذهب إلى آخر جدول في الصفحة واقرأه واقرأ الملاحظة المكتبوبة باللون الأحمر تحته ، ففيها أوقات التسجيل بالنسبة لحالتك أنت .\n\nملاحظة : عند ذهابك للـ UEP DIERCTOR ، وهو الـ Mr.Gibson لا تنس أن تأخذ معك نسخة من جدولك للفصل 052 لكي تختار الوقت الذي لايتعارض مع المواد الأخرى التي تدرسها في السنة التحضيرية .\n\nنصيحة أخوية ، عندما قبل أن تذهب للسيد جبسون تأكد من السكاشن المفتوحة والمدرسين وقم بالسؤال عن أفضلهم ، مع أنه عادة لا يكون لك مجال كبير للاختيار ولكن حاول ذلك عن طريق الرابط:\n\nhttp://regweb.kfupm.edu.sa/Student/course_open3.asp\n\nوهناك مجموعة من المدرسين الذين أنصحك بهم ، والأمر يعود لك :\n\nولكن قبل ذلك أريد أن أحذرك من شخص اسمه MURRAY D هذا الشخص لا يجيد الشرح ومهما بذلت جهدا في المادة وخاصة في الكتابة-101 معظمها كتابة- فلا يعطيك الدرجة التي تستحقها .\n\nأنصحك بالأسماء التالية\n\nMcLAREN P\n\nCONGREVE\n\nISMAIL A\n\nأنا سأتكلم عن Mclaren لأنني درست عنده\n\nشرحه ممتاز ولا يعلى عليه.\n\nإذا بذلت جهدك سيعطيك الدرجة التي تستحقها وزيادة .\n\nصدره مفتوح للأسئلة ، ولا تترد بزيارة مكتبه .\n\nبالنسبة للآخرين CONGREV & ISMAIL A فأنا سمعت من زملائي أن شرحم جيد جيدا ، وسمعت أن كونجريف متساهل في الدرجات .\n\nبالنسبة لـ MURRAY D فقد أخبرتك عنه منذ البداية ، لا تجعله أحد خياراتك أبدًا.\n\nبالنسبة لـ PRYOR R فأنا لا أعرف شيئًا عنه ، ولكن غالبا ما تكون أوقاته غير مناسبة للطلاب\n\nوالرأي الأول والأخير لك أخي “راايق”\n\nأعتقد أن هذا شرح كافي ووافي ، لأنني أنا مررت بمثل ما مررت به أنت الآن وعديت 002 وأخذت 101 في الفصل الثاني\n\nنسألكم الدعاء\n\nأخوك\n\nأبو جاسم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl002/49732/2", "user": "masm007sa", "ts": 1139583036000, "tid": 49732, "pn": 2}}', 1139583036000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p271773-engl002', 'stk-user3033', 'ENGL 002', 'info', '{"desc": "🌹يا أخــوي هذا الكلام أنا متــفق معاهـ …\n\nو أنا نسخت لك كلام أخــوي ( s2007xxxx ) … وهذا غــالب الظــن لإن مدرسنا قال هالكـلام … و أغلب الطلاب يقولون هالكلام …\n\nهذا كـلام أخــوي (s2007xxxx) …\n\n\" بالنسبة لREADING ذاكر BOOK 4 الى TEXT 28 راح تجي 3 تكست واحد من الكتاب واثنين من برا\n\nبالنسبة لLISTENING راح يكون اكيد من برا المنهج تستمع للكونفرسايشن وتاخذ نووت تالي تجاوب\n\nوبالنسبة لWRITING راح يكون سؤالين\n\nالاول COMPARE & CONSTRACT\n\nالثاني WRITE 3 PARAGRAPHS TO DESCRIBE SOME THING \"\n\nوبالتووفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/63520/5", "user": "user3033", "ts": 1212706570000, "tid": 63520, "pn": 5}}', 1212706570000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p559594-engl002', 'stk-user4636', 'ENGL 002', 'info', '{"desc": "اخوي لاتخاف لأن هذا اكبر دليل على حرص مدرسكم\n\nخاصه لو كانت الاوراق ريدنق ولا رايتنق ولا لسننق هذا يعدوكم على اختبارات الجامعه\n\nلأن وقت المياجر راح تعرف ان الكتاب ماله اي علاقه !!!\n\nالا ببعض المواضيع بس لكن اغلبها تعتمد على معلوماتك ولغتك انت كطالب\n\nفا هذا المدرس هدفه من هذي الاوراق ((والله اعلم)) انه يبي يطور لغتكم عشان اذا جا اي اختبار سواء 001 او 002 او حتى لو من انجلش الجبل تصيرون مبدعين وتقدرون تحلونها لأنكم طورتوا لغتكم اكثر وتعلمتوا كلمات اكثر\n\nاما لو يمشي فقط على منهج الكتاب ماراح تستفيد الا ل001 بس!!!\n\nراح تحصل الفايده وقت المياجر والفاينلز وايضا بانجلش الجبل وبتذكر دكتورك بكل خير ان شاء الله\n\nبالتوفيق وفالكم البيرق 😆\n\nقصدي الاونر 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002/84944/6", "user": "user4636", "ts": 1267872242000, "tid": 84944, "pn": 6}}', 1267872242000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p578924-engl002', 'stk-user6810', 'ENGL 002', 'info', '{"desc": ";)بسم الله الرحمن الرحيم\nاولا:الرايتنق:الاختبار ان شاء الله راح يكون قسمين:\n1)وصف شخص او شي او مكان.\nمثلا يطلب وصف انسان والافكار راح تكون (العمر,الاسم,العائله,الوظيفه,المواهب,ما يحب وما لا يحب).وتكون اكثر من 150 كلمه\n\n2)تكتب رايك في عباره معينه مع ذكر اسباب.\nمثلا(منع التدخين في الجامعه)وراح تكون اكثر من 200 كلمه\nالمده بس مني متاكد 90 دقيقه للقسمين.\n\nوعشان تعرف الوقت والمكان:http://www.kfupm.edu.sa/pyp/.\n\nاما الريدنق واللسيننج كلعاده. ;)مع تمنياتي للجميع بالتوفيق 😉", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl002-let-s-play-with-it/86267/2", "user": "user6810", "ts": 1270037115000, "tid": 86267, "pn": 2}}', 1270037115000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1169167-engl002', 'stk-me203', 'ENGL 002', 'info', '{"desc": "أولا شي مافي شي صعب\nلكن انت محتاج تشد حيلك في الرايتنق أكثر من الـ01 بكثير + لا تهمل في القرامر و الفوكاب لانه نفس منهج الـ01 لكن طريقة وضع السؤال تصير اصعب شويه ، خذ وقتك في الاجابة … + التوفل ما هو صعب بالصعوبة الي كانت موصوف بها ، بالنسبة للـ 500 فنا ماجبتها فشوف شباب الـ04 أكثر خبرة مني … هذا و صلَ الله و بارك على سيدنا محمد …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-02/138866/3", "user": "ME203", "ts": 1359121210000, "tid": 138866, "pn": 3}}', 1359121210000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1169169-engl002', 'stk-dyaa94', 'ENGL 002', 'info', '{"desc": "وعليكم السلام\nانا مادرست 02 بس اقدر افيدك بالتوفل…منهج 04 50% منه دراسة توفل يعني انت بتخلص الكورس وبتكون في السليييييم…من واقع تجربه انا اول مادخلت الجامعه جبت درجة نوعا ما سيئة وحسيت التوفل صعب جدا لكن اول ماخلصت 04 التوفل صاررر اسهل مايكون\nنصيحتي لك…اذا كنت ناوي تاخذ بروموشن بعد 02 على طول شف لك كتاب التوفل اللي يعطونه لطلاب 04 وذاكره مذاكره طيبه قبل الاختبار وانشاء الله تعدي بالرااااحه\nاتمنى اني افدتك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-02/138866/4", "user": "Dyaa94", "ts": 1359121705000, "tid": 138866, "pn": 4}}', 1359121705000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p601631-engl002', 'stk-kfupm_prince', 'ENGL 002', 'info', '{"desc": "السلام عليكم …\n\nكل شي عادي بس التوفل هو اللي يخوف ؛ يعني لو قارنا مستوى الاختبارات بالتوفل فرررق ! كان خلوا عليها 5% زي اول عالاقل خخخ …\n\nبالنسبة للي بيد المدرس حرام >< بس ولو أشوف إنها أهون من السبيكينق أول اللي ممكن بالمزاج يعطونك درجة تحت !\n\n- بما انك دخلت التوفل ؛ اممم تنصح نراجع شي معين قبل الاختبار …؟ والقرامر هل هو صعب كثير يعني يحير …؟\nلأنه التوفل سمعت انه توفل الانترميديت يعني مب الأساسي الصعب …؟\n\nمشكور أخوي علي ؛ وبالتوفيق بالماث …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/welcome-to-hell-info-about-eng-002-final-exam-and-somethig-else/87741/5", "user": "KFuPM_PRinCe", "ts": 1273262324000, "tid": 87741, "pn": 5}}', 1273262324000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p601766-engl002', 'stk-user5812', 'ENGL 002', 'info', '{"desc": "بالنسبة للتوفل\n\nشباب لا يغركم اسمه والكلام عنه\n\nوالله ثم والله ثم والله\n\nانه سهل\nبس يبغاله تركيز\n\nانا في ٠٠١ ما اخذت بروموشن\n\nبداية السمستر الثاني اختبرت التوفل عشان البروموشن\n\nالحمدلله اخذت ٥٨٠ كأعلى درجة في الكلاس\nوتبرمشنت 😆\nشوفوا هذي نصايحي لكم :\n\nقسم اللسننق بتسمع الجملة ومن ثم عندك ٥ ثواني تقريبا تختار\nفلازم تكون مركز مرة\nقسم الريدنق اصعب شي لأنه القطع طويلة ويبغالها فهم وسرعة قرائة واختيار\nاذكر جاتنا القطع عن : المخلوقات في اعماق المحيطات ، الهنود الحمر ، الفن التشكيلي … الخ ما اذكر الباقي 😆\n\nاما القرامر والفوكاب يبغاله تركيز\nاستبعد الإجابات المستحيلة وخلي الباقي ومن ثم اختار\n\nولا تضييييييع وقت اهم شي\nإن ما عرفت شي ظلل اي حاجة وكمل لأنك لو ضيعت من وقتك شوي عليه بيكون راح عليك السؤال اللي بعده .\n\nاهم شي لا تكون عندك رهبة\nاذكر لما قالولنا اختبار البروموشن هو اختبار التوفل\nوربي كنت خايف\nلأني كنت اسمع عنه . توفل توفل توفل شي يفجع وربي خخخخخخخ\nلكن بعد ما اختبرت الحمدلله وسمعت درجتي ارتحت كثيييييييير\n\nفلا يغركم الإسم\n\nوبالتوفيق لنا ولكم ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/welcome-to-hell-info-about-eng-002-final-exam-and-somethig-else/87741/10", "user": "user5812", "ts": 1273269886000, "tid": 87741, "pn": 10}}', 1273269886000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p767246-engl002', 'stk-charisma', 'ENGL 002', 'info', '{"desc": "الإختبار سهل جداً ولله الحمد …\nالليستنق تقدر تجيب الإجابات الصحيحه من أول مرة … والمرة الثانية للتأكيد فقط !\nبعده يجيك الفوكاب & القرامر … سهل جدا واجوبه بديهية يعني والفوكاب سهلة وبسيطة …\nالريدنق يتكلم عن ( طاقة الرياح والمياه وتأثيرها على الطاقة في المملكة المتحدة ) مقسمة على 4 قطع , بعدها 4 أسئلة العنوان المناسب لكل قطعة … وبعدها اسئلة عن معنى كلمات في القطعة ( سهلة وحتى لو ماتعرفها تفهمها من السياق )\n\n… الإختبار سهل يبغاله بس تركيز وخلاص ( شيء طبيعي لانه من برا الجامعة !! )\n\nاتوقع الأفرج راح يكون من 78 الى 82 .\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-technology2/100976/16", "user": "Charisma", "ts": 1295510777000, "tid": 100976, "pn": 16}}', 1295510777000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p767280-engl002', 'stk-user6182', 'ENGL 002', 'info', '{"desc": ",’\n\nخآف الله يا رجل !\nالله لا يقوله … 😲\n\n,’\n\nالإختبار بسيط يا شباب , مثل ما قال كاريزما …\nشويه تركيز , على كوب قهوة قبل تدخل , وتوكل على الله وحلّ …\n\n,\n\nفيه سؤالين غلط باللسننق , راح ينبهكم عليها المدرس بدآية الإختبار …\n( طبعاً هذا إذا كان اللسننق نفسه اللي في الصباح )\n\nفوكاب مش كثير , حوالي 10 كلمات فقط , وكلّهآ سهلة …\nفيه وحدة بس معقدتني من الإختبار الأول إلى الآن , ومدري وش سالفتها …\nوهي اللي تجي الخيارات فيها من نوع \" الكترونك , ولاّ إلكترونيكال , ولا إلكترستي … إلخ \" --> قسّيتها طبعاً 🙂 ❤️\n\n,\n\nاللسننق ثلاث حبّات , كل حبّة حوالي 9 اسئلة …\nوحدة مقابلة مع شخص , والثانية مكالمة بين شخص وشركة أو مكتب توصيل أو شئ زي كذا …\nحآول تكون قريب من السماعات , لأن الصوت والأكسنت رايح فيها …\nالترك كثير , وما فيه وقت إضافي للببل …\nيعني اسمع من هنا , وشخط في ورقة الاجابة من هنا …\n\nموجودة … 🌹\n\n,\n\n70 سؤال , ثلث في اللسننق , وثلث فوكاب وقرمار , وثلث مقسم بين الريدنق والخرابيط اللي في الأخير ( however …etc ) …\n\n,\n\nعآمة طبعاً , بس فيها اقتباسات كثير من الكتاب ,\nيعني تكلم عن الربورتات , وتكلم عن منازل المستقبل … إلخ ,\n\nبس حتى لو ما دريت وش حاطين بالكتاب ,\nتقدر تستوعب المحادثة كلها …\n\nبالنسبة لي , 8 الصباح …\nوآتوقع عشرة نفس الإختبار …\n\n,’\n\nموفقين إن شاء الله يا شباب …\nدعواتكم بس … ❤️\n\n🌹\n\n,’", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/002-technology2/100976/21", "user": "user6182", "ts": 1295514588000, "tid": 100976, "pn": 21}}', 1295514588000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p596343-engl002', 'stk-user5628', 'ENGL 002', 'info', '{"desc": "لا تشيل هم …\nزي ما قال الأخ ، عليها 26% …\nولا تنسى ان 25% في يد المدرس ، يعني تقريبا تعادل اختبار الميد تيرم للسننق والريدنق والرايتنق ، فلذلك حاول انك تستغلها …\nأيضا ،، 39% للفاينل (ريدنق ، لسننق ، رايتنق) ، …\nو 10% على التوفل …\nفما زال امامك فرصة كبيرة جدا لتحسين وضعك ، وان شاء الله تعدي المادة بدرجات حلوة بإذن الله …\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002/87352/4", "user": "user5628", "ts": 1272558754000, "tid": 87352, "pn": 4}}', 1272558754000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p196311-engl002', 'stk-user1091', 'ENGL 002', 'info', '{"desc": "بسم الله\n\nإي نعم صحيح\n\nالاختبار اسمه اختبار الترقية (برموشن بالانجليزي Promotion) إذا نجحت فيه تدرس انجلش 002\n\nوفي اختبار ترقية ثاني لإنجلش 002 إذا نجحت فيه تقدر تدرس انجلش 101 في الجبل\n\nلكن أنا دائما أنصح الطلاب اللي يجيهم برموشن لا يغترون كثير لأنه دخولهم هذا الاختبار ليس دليل على تميزهم في الانجليزي\n\nفإذا إنت تحس من نفسك إنه انجليزتك ضعيفة لا تدخل الاختبار أصلا\n\nلأنك في الجبل ستعرف مدى حاجتك لإنجلش 001 وانجلش 002 فالدراسة في الجبل كلها بالانجليزي ما عدا بعض الكورسات القليلة جدا تكون الدراسة فيها بالعربي\n\nأما إذا شفت نفسك ما تحتاج تتحسن لأن انجليزتك قوية فادخل الاختبار والله يوفقك\n\nوالتوفيق من عند الله أولا وأخيرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/58180/4", "user": "user1091", "ts": 1188507153000, "tid": 58180, "pn": 4}}', 1188507153000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p858056-engl002', 'stk-titol', 'ENGL 002', 'info', '{"desc": "فقط لمن عاد eng 002 معلومات هامة …\n\nاخواني الاعزاء\nالسلام عليكم ورحمة الله وبركاته …\nهذه المعلومات فقط لمن عاد eng 002 …\nحبيت استفسر عن معلومات هامة جدا من ناحية كورس eng002 للطلاب اللي بياخذونه باذن الله تعالى بالصيف ومن ضمنهم انا …\n1- كم عدد اسابيع الترم الصيفي بالضبط شاملة لاسبوع الاختبارات ؟\n2- كم عدد ساعات الدوام الرسمي وهل عادتا يكون مساعدة من ناحية الاستاذ انه يطلع الشباب بدري ام لا ؟\n3- غالبية الشباب اللي يعيدون ينقلونهم ليفل اعلى من الليفل الاول بدرجة هل هنالك كتب جديدة لهم ام لا ؟\n4- كم عدد الاختبارات القصيرة الاسبوعية اي بمعنى كم عددها بالاسبوع وكم مجموعها كلها مع العلم انه لدينا 12 الى 13 اختبار قصير بالترم العادي وموزعة اختبار لكل اسبوع\n5- كيف الاساتذة من ناحية الدردجات هل يتساعدون مع الطالب ام لا لانه كثير ن\\من الشباب سمعوا انه هنالك تساهل كبير ؟\n6- هل عادتا يكون هنالك نساهل وفترة عدم ضغط خصوصا للفترة التي تسبق اختبار الميد تيرم ام لا مع العلم انه الصيف مضغوط دوامه ومتى راح يكون الميدتيرم ان شاء الله في الاسبوع الكم اقصد وهل يكون اسهل ام متوسط ام صعب عادتا ؟\n7- وهل تكون نسبة نجاح كبيرة بالصيف ولا لا …\n\nوجزاكم الله الف خير . ❤️ 🌹 🌹 ❤️… والسلام عليكم ورحمة الله وبركاته .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/108578/63", "user": "TITOL", "ts": 1308852464000, "tid": 108578, "pn": 63}}', 1308852464000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p167651-engl002', 'stk-user1725', 'ENGL 002', 'info', '{"desc": "حسبنا الله ونعم الوكيـــــل !!\n\nاسبوعين وزياده عشان الدرجات >> لعب عيني عينك …\n\nكلامك صحيح دارك سكريم وانا اشهد درجاتك في الترم الاول ماشاء الله حلووه\n\nويجيك الحين في الترم هذا لعب !!\n\nانا جبت درجه كويسه وفوق الافرج بكثير … لكني توقعت اجيب اكثر من كذا …\n\nوللأسف ماشفت درجات الرايتنق والريدنق … كنت مستعجل هع\n\nعلى حسب ما سمعت من بعض الطلاب انو بعضها غلط … وسيتم تعديلها السبت !!!\n\nوقبل شويه عالساعه 4 ونص … وجدت تجمعات من الطلاب على غرفه مستر بولز !!مدري ليش !!\n\n:: عزووز ::", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/56230/6", "user": "user1725", "ts": 1178720166000, "tid": 56230, "pn": 6}}', 1178720166000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p167678-engl002', 'stk-3b_d_u_l_l_a_h', 'ENGL 002', 'info', '{"desc": "لنا الله !!\n\nانا نفس الشي درجاتي 49 reading !!! (( مع ان السمستر الاول بكل الاختبارات عمرها مانزلت عن 75 )) !!\n\n75 writting درجة معقولة ومتوقعة بالنسبة للي كتبته (( يعني ماتفاجأت …))\n\n62 listening ((برضو معقولة وتمشي الحال …))\n\nمدرسنا مستغرب من درحات الreading ويقول راح اجيب لكم الاوراق بس مالكم امل تغيرون بالدرجات !! تحطيم عيني عينك@4@\n\n__\n\nقفلة : نتمنى تدخل السلطة العليا بالجامعة …\nكلنا امل بوالد الجميع الدكتور خالد …\n\n__", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/56230/8", "user": "3b_d_u_l_l_a_h", "ts": 1178724146000, "tid": 56230, "pn": 8}}', 1178724146000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p167844-engl002', 'stk-user1655', 'ENGL 002', 'info', '{"desc": "شوفوا يا أوريات\nأنصحكم بعمل تجمع لكل أوريات 002 وكل واحد معه مرزبة أو عصايا ، وموعدكم يوم السبت عند مكتب بولز وخلوا العصي تتفاهم معه…\nأمزح معكم ،\nأنصحكم من جد الذهاب للدكتور الصويان ، عميد الشؤون الأكاديمية وهو راح يصلح لكم الوضع بإذن الله ، الدكتور صاحب خلق حسن ويحب مساعدة الطلاب ، وأنتم أصلا الحق معكم وبولز هذا ما له حق أصلا بتنزيل الدرجات كما أنه ليس له حق بزيادة الدرجات …\n\nإذا ما لقيتوه عليكم بالدكتور السلطان …\n\nإذا ما لقيتوه فعليكم بدعاء من يجيب المضطر إذا دعاه ، الذي لا تأخذه سنة ولا نوم وراح تنحل…\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/56230/22", "user": "user1655", "ts": 1178798343000, "tid": 56230, "pn": 22}}', 1178798343000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p435670-engl002', 'stk-user4591', 'ENGL 002', 'srcP', '{"html": "سم اخوي جبته لك من واحد من اخوياي<br><br>طبعا الملف وورد وفيه الفاينل والميد ترم<br><br>طبعا بتقولي شلون افرق بينهم<br><br>الميد تيرم راح انظر الى الرايتنق وشوف المواضيع راح تشوف الشكوى والقصه يعني هذا الميد تيرم<br><br>اوكى اخوي وفالك البيرق باذن الله<br><br>​<span data-fid=\"stk-f435670-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f435670-0": {"name": "مهم.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/9f138cb54acf6a6dd92c94fbe4ced44573414078a2e5bae08c4b0d1692b4c36c"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng002/75831/6", "user": "user4591", "ts": 1248431025000, "tid": 75831, "pn": 6}}', 1248431025000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p168493-engl002', 'stk-user1602', 'ENGL 002', 'srcP', '{"html": "تماااام … تمااااام عليييكم<br><br>…<br><br>نفس الشئ سويناه على دفعتنا بس هذيك الأيام … كنا على أساس تغيير أوقات الفاينلات نبغى نخليها على يومين …جمعنا التواقيع وكتبنا خطاب باللغه العربيه فقط مردوفا بسبع صفحات تحمل تواقيع الطلاب… وتوجهت مع ستة طلاب من زملائي الأوريا…يوم الاثنين الساعه 12:30 وحنا داخل مكتب الدكتور خالد السلطان … كان متفهم واستمع لنا ولمعاناتنا وشرحنا له ضروفنا وش اللي بيصير وش لنا ووش علينا الزبده اللي في الورقه سمعناه اياه …وكان في نفس الوقت وحنا نتكلم يطالع صفحات التواقيع …ويقول وهو مستغرب كل هذول الطلاب موافقينكم … ردينا عليه سريع سريع قلنا اييه يادكتور وحنا يالطلاب ياللي تشوفنا الحين نيابه عنهم وكلامنا هو كلامهم وموافقين عليه وموقعين بعد<br><br>…<br><br>الزبده http://www.skfupm.com/vb/images/icons/icon10.gif فيه ملف وورد مرفق لكيفية التواقيع مع وضع الآيدي … سوو له برنت ووزعوه على ثمانيه سكاشن …كل سكشن بورقه لحاله … ووقت البريك بكره وانتو في مبنى 21 الدور الـ 9 .<br><br>وبالتووفيق لكم … وقلوبنا معااكم<br><br>​<span data-fid=\"stk-f168493-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f168493-0": {"name": "ID + Signature.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-002/56290/17", "user": "user1602", "ts": 1179088801000, "tid": 56290, "pn": 17}}', 1179088801000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p635110-engl002', 'stk-s_h_a_d_o_w', 'ENGL 002', 'srcU', '{"html": "السلام عليكم ورحمة الله وبركاته<br><br>البرنامج عبارة عن ملف اكسل تدخل فيه درجاتك الي حصلتها طول<br>السمستر ويعطيك درجتك النهائية<br><br>طبعا بما ان التوفل ما نزل درجاته فراح تترك خانة التوفل 0<br><br>​<span data-fid=\"stk-f635110-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f635110-0": {"name": "English 002.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002/90214/1", "user": "S_H_A_D_O_W", "ts": 1276685299000, "tid": 90214, "pn": 1}}', 1276685299000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p69593-engl002', 'stk-user782', 'ENGL 002', 'srcU', '{"html": "هذه ورقة قمت بعملها لتلخيص الوحدات 1و 3 و 5 المتعلقة بموضوع Relative clause، آمل منكم الاستفادة منها.<br><br>تم رفعها أيضاً إلى skfupm.org وبانتظار موافقة المشرف عليها.<br><br>تحياتي لكم<br><br>​<span data-fid=\"stk-f69593-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f69593-0": {"name": "032_engl002_abduh.net_relativeclause.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/relative-clause-engl002/45307/1", "user": "user782", "ts": 1109240234000, "tid": 45307, "pn": 1}}', 1109240234000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p584905-engl002', 'stk-s_h_a_d_o_w', 'ENGL 002', 'srcP', '{"html": "السلام عليكم ورحمة الله و بركاته<br><br>في المرفقات راح تلاقي معلومات عن اختبارات الـ Writing - Reading - Listening<br><br>---------------------------------------------------------------------------------------<br>و اذا تبغى تعرف مواعيد اختباراتك اضغط هنا<br><br>​<span data-fid=\"stk-f584905-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f584905-0": {"name": "Mid-term exam Int (details for students)[1].doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002-mid-term/86630/1", "user": "S_H_A_D_O_W", "ts": 1270646490000, "tid": 86630, "pn": 1}}', 1270646490000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p585515-engl002', 'stk-alghrafy', 'ENGL 002', 'srcP', '{"html": "عفوا الملف في المرفقات<br><br>​<span data-fid=\"stk-f585515-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f585515-0": {"name": "Int 2010 MCA test specs KSA.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/51c81d48adbe7f0b560019e2ec42073922bdb2bf4f7089ac74b05d6de9f05429"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-002-mid-term/86630/14", "user": "alghrafy", "ts": 1270715554000, "tid": 86630, "pn": 14}}', 1270715554000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-engl002', 'stk-user4988', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f68550", "n": "Dr. John Armstrong", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "engl 002\n082\n\nأحياناً أترحم على أيام الأوريا … ما أدري ليش 😆\n\n؟؟؟؟؟؟؟؟؟؟؟\n\nصراحة أمر هذا الرجال غريب من وقت ما قرينا إسمه …\n\nإسمه في البورتال : JOHN ARMSTRONG\nبينما لما جانا في أول السمستر … قال إن إسمه : Neil ARMSTRONG\n\nو على نهاية السمستر و في وقت الإيفالويشن لما سألناه عن سبب إختلاف إسمه في اللي مكتوب في البورتال …\nرد علينا بإبتسامة مطاطية : this is not your business\n\nفما أدري … أحد عنده علم ؟؟؟\n\nعلى العموم بأقيمه كـ Neil ARMSTRONG :\n\nالتحضير : موسوس و حريص جداً على التحضير … أحياناً تجيه خمقة و يقوم يرتب الكلاس كل كرسيين بجنب بعض و يرقمها … و بعد كذا يعطي لكل واحد رقم يقعد عليه لمدة أسبوع … و بعد كذا يغير !!\n\nطريقة الشرح : بشكل عام ممتازة … يستخدم الصور و الفيديوز أحياناً … مرة جاب لنا مقطع عن خوينا مستر بين لما يحاول يغش في الإختبار … و طلب منا نكتب قطعة نصية عن اللي حصل معاه 😆\n\nالكويزات : متوسطة ككل … قد تكون راينتق أو فوكاب … بس قبل الكويز … لازم يقلب الكراسي فوق تحت و يرتبها بحيث إن كل الكراسي تقريباً يخليها جهة الجدار يمين السبورة عشان ما أحد يغش … أم الحووووووووسة 😆\n\nالمياجر:كومن\nالفاينلات :كومن\n\nالقريد النهائي: أنا أعطيه بين a و b+\n\nالصوت:واضح …\n\nإضافات :\nزي ما قلت … تقيمي هذا لـ Neil ARMSTRONG … ما أدري يمكن غير اسمه او إن هذا أخوه التوأم … ما ادري …\n\nصح إن عليه طلعات غريبة … بس دامك شغال معاه … إن شاء الله تخرج بقريد …\n\nو الله الهادي إلى سواء السبيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p729311-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-armstrong/68550/7", "user": "user4988", "ts": 1288435172000, "tid": 68550, "pn": 7}}]}', 1288435172000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-badr_15-engl002', 'stk-badr_15', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f68556", "n": "Dr. John Martin Carey", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درسني engl002\n\nالتحضير : زي ماقالوا الشباب حبيب مره\n\nطريقة الشرح : شرحه ممتاز ويسوي حركات دلع ؛)\n\nالقريد النهائي:+B\n\nالصوت: واضح وهادئ\n\nإضافات : بالنسبه لي بنزل عنده بس الخوف انه يصير ملخبط لأنه أول مره يدرس في الجبل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p528295-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/carey-john-martin/68556/12", "user": "badr_15", "ts": 1264358328000, "tid": 68556, "pn": 12}}]}', 1264358328000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7684-engl002', 'stk-user7684', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f118976", "n": "Dr. Frederick Wallace", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مستر فريد وما ادراك ما مستر فريد\nكنا حنا فيران التجارب في ديبارتمنت الانجلش جاء فريد بعد شهر من بداية الترم وكان هو اول مرة يطب السعودية واول مرة يطب الجامعة واول مرة يطب على وجيهنا 🙂\n\nترم 102 … ENGL-002-a\nالتحضير : مسكات مرة يحضر ومرة لا …\nطريقة الشرح : توب التوب … يشرح لك الوورد لست بطريقة ممتعة بحيث انك تعرف معنى ابو الكلمة وتعرف متى تستخدمها …\nالكويزات : كومون … بس تحضيره لها احتراف …\nالمياجر : كومون\nالفاينلات : كومون\nالصوت : 8 / 10 … يعيبه الاكسنت (( آيروش ))\nالقريد : B+\nاضافات : نظامه فله مع الطلاب حتى لو بغيت يقعد يسولف معك ساعة بعد الكلاس وغاليا يتشكى من زوجته الكورية … ويتكلم عن ولده وبنته (( جوجو و نانا ))\nالمدرس ضخم … بس لا تخاف ترا قلبه طيب …\nغالبا يستلم واحد او اثنين من الكلاس اللي مو عاجبينه ويقطع فيهم … بس في النهاية يقول هذا للفايدة 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974667-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-wallace-frederick/118976/4", "user": "user7684", "ts": 1327689219000, "tid": 118976, "pn": 4}}]}', 1327689219000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-engl002', 'stk-mr.a1', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f172420", "n": "Dr. John Lauder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lauder, John\n\nEmail : jlauder@kfupm.edu.sa\n\nTERM 141 ENGL 02\n\nبنود التقييم :\n\nالتحضير :\nكان يعطينا بارت تايم مع مدرس ثاني ، يحضر كل كلاس من الكلاسين اللي يدرسنا اياهم في بداية الكلاس\nطريقة الشرح : يفتح نسخة الكترونية من الكتاب على البروجيكتور ، يناقش الطلاب ويشرح الفوكاب بطريقة جميلة\nالنقطة اللي اعجبتني فيه هي فهمه للقرامر واتقانه وشرحه الممتاز له ، خصوصا ان القرامر كثير في 02 واغلبه يعتبر اساس في اللغة\nبالنسبة لكتاب الريدينق والرايتينق كانت عند المدرس الثاني ( ستيفين هينيسي )\nالكويزات :\nاختبارين بروغرس ، كومن\nالمياجر:\nميد ترم كومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA ، نفس قريدي اللي طلعت فيه\nالصوت:\nجيد جدا ، لا هو منخفض ولا مرتقع\nإضافات:\nالمدرس كويس وما عليه كلام ، لكنه ما هو قريب من الطلاب بشكل كبير ، يعني تحسه يؤدي عمله ، وممكن انه يدخل في نقاشات خفيفة وتعليقات بسيطة مع الطلاب\nاللي لاحظته عليه إنه مو مثل بعض مدرسين الانجلش اللي ينكتون كثير ويسولفون مع الطلاب ، لكنه معلم جيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1443190-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lauder-john/172420/2", "user": "Mr.A1", "ts": 1456482801000, "tid": 172420, "pn": 2}}]}', 1456482801000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-engl002', 'stk-sultan_salman_1419', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f172424", "n": "Dr. John Baker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl02 … Term 161\n\nالتحضير : في بداية الحصة ويحضر في كل فترة\n\nطريقة الشرح : مميز في القرامر وجيد في الأقسام الآخرى\n\nالكويزات : يوزع كويزات بشكل دوري ويصححها باستمرار … ما أعتقد بتأثر كثير من ناحية الدرجات\n\nالمياجر: مافيه\n\nالفاينلات : مافيه\nالقريد النهائي: +B\n\nالصوت: ضعيف نوعا ما … لازم تجلس في المقدمة\n\nإضافات : رغم تميزه في شرحه ولكن شرحه بعض الأحيان ممل لدرجة انك تعد دقائق الحصة دقيقة دقيقة عشان يخلص الكلاس بالذات في الصباح … يعطي كم نكتة … أغلبها ما تضحك ولكن يكفيه شرف المحاولة … متعاون في الاوفيس اور … يرسل في الايميل ملخص لكل وحدة ( قرامر ) بيفيدك كثير حتى لو كنت في 04 … أيضا يرسل قبل الاختبارات بعض الاسئلة ( لسننق … قرامر ) … مفيدة جدا … حلها قبل الاختبار وراح تستفيد كثير .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1481576-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-baker/172424/4", "user": "sultan_salman_1419", "ts": 1507561458000, "tid": 172424, "pn": 4}}]}', 1507561458000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-engl002', 'stk-kirsty13', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f175784", "n": "Dr. Stephen Gill", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL02-SH53( سكشن تيييييييتشر ❤️ :slightly_smiling_face:)\n\nالتحضير : يحط ورقة التحضير ف الجدار وانت تحضر نفسك ,سهالات جداااا, تخش في اي وقت يا يقول سجل حاضر او كلمته الشهيرة Big Fat L, مرات يعد ورا الطلاب ويشوف من محضر خويه 😏 لكن لو قفط عطه اي تصريفه ولا يقول شي.\nطريقة الشرح : كان يعطينا ريدنق ورايتنق. شرحه بسيط وجميل , من ناحية الرايتنق فهو كويس مو ممتاز كثير لكن الريدنق ممتاز فيه واستراتيجياته ممتازة وفادتني كثير + اذا احد قاله طفشان ولا شي سكرنا الكتب وفتح لنا موقع او يوتيوب ونتناقش معه باختصار متعة متعة لابعد درجة وتطور اللغة وتستفيد .\nالكويزات : مافي\nالمياجر: من الديبارتمنت\nالفاينلات : الديبارتمنت\nالقريد النهائي: طلعت ب A, معاه واعطيه +++++++++A\nالصوت: ممتاز وواضح جدا ولايجيب النوم ولاهو اللي يصارخ\nإضافات : بريطاني من ليفربول ويكره استراليا كره ما تتصوره 😂.من افضل الناس اللي بتمر عليك بالجامعة اذا انت ماخذ الانقلش كلغة وتحبها مو عشان الدرجات بتسمتع جدا .من ناحية الغيابات خلك مضبوط معه وخله يعرفك انك كويس وبترتاح, اتذكر غبت حوالي 11 مرة عنده الذيب سجلها 4 غيابات و 3 ليت بس. الدكتور يحب يعطي كل طالب لقب ولا يناديه الا فيه وجدا مزوحي ويتقبل المزح. يسمونه بدفعتنا الفخم لانه تصحيحه فخم على ما ينقال ويدفك 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505152-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stephen-gill/175784/9", "user": "Kirsty13", "ts": 1548036717000, "tid": 175784, "pn": 9}}]}', 1548036717000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest333-engl002', 'stk-guest333', 'ENGL 002', 'doc', '{"docs": [{"id": "stk-dr-f185998", "n": "Dr. Shiyam Azwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : ENGL 02\n\nالتحضير : شديد على التأخير يحضر بالوجوه يحفظ الطلاب اول يومين، ساعات لما تتأخر تقوله نكات انجليزية يمشيك.\nطريقة الشرح : القرامر تقريبا مو متمكن منه وصعب تفهم منه قرامر، الكلمات شرحه لها جيد لممتاز . الرايتنق كان شغال علينا فيه يسوي تدريبات كثيرة له قبل الاختبار.\nالكويزات : N/A\nالمياجر:N/A\nالفاينلات : موحد\nالقريد النهائي: اعطيه b+ اذا كان يدرسك 02 لأنه الكوردينيتر اما في الباقي b\nالصوت: واضح لهجة كندية\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539545-engl002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shiyam-azwar/185998/2", "user": "guest333", "ts": 1746978355520, "tid": 185998, "pn": 2}}]}', 1746978355520, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
